#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
char*s=parse("# Header!\n* __Bold__\n* _Italic_\nplain");assert(!strcmp(s,"<h1>Header!</h1><ul><li><strong>Bold</strong></li><li><em>Italic</em></li></ul><p>plain</p>"));free(s);s=parse("####### not heading");assert(!strcmp(s,"<p>####### not heading</p>"));free(s);s=parse("__a__ and __b__");assert(!strcmp(s,"<p><strong>a</strong> and <strong>b</strong></p>"));free(s);
{char*actual=parse("This will be a paragraph");assert(!strcmp(actual,"<p>This will be a paragraph</p>"));free(actual);}
{char*actual=parse("_This will be italic_");assert(!strcmp(actual,"<p><em>This will be italic</em></p>"));free(actual);}
{char*actual=parse("__This will be bold__");assert(!strcmp(actual,"<p><strong>This will be bold</strong></p>"));free(actual);}
{char*actual=parse("This will _be_ __mixed__");assert(!strcmp(actual,"<p>This will <em>be</em> <strong>mixed</strong></p>"));free(actual);}
{char*actual=parse("# This will be an h1");assert(!strcmp(actual,"<h1>This will be an h1</h1>"));free(actual);}
{char*actual=parse("## This will be an h2");assert(!strcmp(actual,"<h2>This will be an h2</h2>"));free(actual);}
{char*actual=parse("### This will be an h3");assert(!strcmp(actual,"<h3>This will be an h3</h3>"));free(actual);}
{char*actual=parse("#### This will be an h4");assert(!strcmp(actual,"<h4>This will be an h4</h4>"));free(actual);}
{char*actual=parse("##### This will be an h5");assert(!strcmp(actual,"<h5>This will be an h5</h5>"));free(actual);}
{char*actual=parse("###### This will be an h6");assert(!strcmp(actual,"<h6>This will be an h6</h6>"));free(actual);}
{char*actual=parse("####### This will not be an h7");assert(!strcmp(actual,"<p>####### This will not be an h7</p>"));free(actual);}
{char*actual=parse("* Item 1\n* Item 2");assert(!strcmp(actual,"<ul><li>Item 1</li><li>Item 2</li></ul>"));free(actual);}
{char*actual=parse("# Header!\n* __Bold Item__\n* _Italic Item_");assert(!strcmp(actual,"<h1>Header!</h1><ul><li><strong>Bold Item</strong></li><li><em>Italic Item</em></li></ul>"));free(actual);}
{char*actual=parse("# This is a header with # and * in the text");assert(!strcmp(actual,"<h1>This is a header with # and * in the text</h1>"));free(actual);}
{char*actual=parse("* Item 1 with a # in the text\n* Item 2 with * in the text");assert(!strcmp(actual,"<ul><li>Item 1 with a # in the text</li><li>Item 2 with * in the text</li></ul>"));free(actual);}
{char*actual=parse("This is a paragraph with # and * in the text");assert(!strcmp(actual,"<p>This is a paragraph with # and * in the text</p>"));free(actual);}
{char*actual=parse("# Start a list\n* Item 1\n* Item 2\nEnd a list");assert(!strcmp(actual,"<h1>Start a list</h1><ul><li>Item 1</li><li>Item 2</li></ul><p>End a list</p>"));free(actual);}
return 0;}
